/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

//---------------------------------------------------------------------------//

UInt32 keeloq_encrypt ( UInt32 data, UInt64 key ) 
{ 
	UInt32 x = data, r; 
	
	for (r = 0; r < 528; r++) 
	{ 
		x = (x>>1)^((bit(x,0)^bit(x,16)^(UInt32)bit(key,r&63)^bit(KeeLoq_NLF,g5(x,1,9,20,26,31)))<<31); 
	} 
	return x; 
} 

